def cobs_encode(payload: bytes) -> bytes:
    if not payload:
        return b"\x01"

    result = bytearray()
    i = 0
    n = len(payload)

    while i < n:
        if payload[i] == 0:
            # Group ends here, count non-zero bytes since last group start
            count = i
            result.append(count)
            i += 1
        else:
            # Count consecutive non-zero bytes
            count = 0
            while i < n and payload[i] != 0:
                count += 1
                i += 1

            if count == n:
                # Reached end without zero
                if count == 254:
                    result.append(255)
                else:
                    result.append(count)
            else:
                # Reached a zero
                if count == 254:
                    result.append(255)
                else:
                    result.append(count)

    return bytes(result)

def cobs_decode(data: bytes) -> bytes:
    if len(data) == 0:
        raise ValueError("Empty input")

    result = bytearray()
    i = 0

    while i < len(data):
        code = data[i]
        i += 1

        if code == 0:
            raise ValueError("Zero byte in encoded data")

        if code == 255:
            # 254 data bytes expected, continue
            if i >= len(data):
                raise ValueError("Trailing code byte 255 without enough data")
            result.extend(data[i:i+254])
            i += 254
        else:
            # code-1 data bytes expected
            count = code - 1
            if i + count > len(data):
                raise ValueError("Group data runs past end of input")
            result.extend(data[i:i+count])
            i += count

    return bytes(result)

