module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  reg [WIDTH-1:0] data_array [0:DEPTH-1];
  reg [2:0] read_ptr;
  reg [2:0] write_ptr;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      data_array <= {DEPTH{1'b0}};
      read_ptr <= 3'b0;
      write_ptr <= 3'b0;
    end else begin
      if (wr_en && write_ptr != read_ptr) begin
        data_array[write_ptr] <= din;
        write_ptr <= write_ptr + 1'b1;
      end
      if (rd_en && read_ptr != write_ptr) begin
        dout <= data_array[read_ptr];
        read_ptr <= read_ptr + 1'b1;
      end
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      full <= 1'b0;
      empty <= 1'b1;
    end else begin
      if (write_ptr == read_ptr) begin
        empty <= 1'b1;
        full <= 1'b0;
      end else if (write_ptr == read_ptr + 3'b1) begin
        empty <= 1'b0;
        full <= 1'b1;
      end else begin
        empty <= 1'b0;
        full <= 1'b0;
      end
    end
  end

endmodule

