__global__ void block_sum(const float* in, float* out, int n) {
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    float sum = 0.0f;

    for (int offset = blockDim.x; offset < n; offset += blockDim.x * gridDim.x) {
        if (idx + offset < n) {
            sum += in[idx + offset];
        }
    }

    sdata[tid] = sum;
    __syncthreads();

    if (tid == 0) {
        out[blockIdx.x] = sdata[0];
    }
}

