            // tanh(x) = (exp(x) - exp(-x)) / (exp(x) + exp(-x))
            // To avoid overflow, use: if x > 0: (1 - exp(-2x)) / (1 + exp(-2x)), else: (exp(2x) - 1) / (exp(2x) + 1)
            // Actually, standard tanh implementation:
            double exp_val = exp(sum);
            double exp_neg_val = exp(-sum);
            h[j] = (exp_val - exp_neg_val) / (exp_val + exp_neg_val);
        }

        // Forward pass for output layer
        for (int j = 0; j < n_hidden; j++) {
            z_final += W2[j] * h[j];
        }
        z_final += b2;

        // Output activation (sigmoid)
        double exp_z = exp(z_final);
        double exp_neg_z = exp(-z_final);
        double p = (exp_z - exp_neg_z) / (exp_z + exp_neg_z); // This is tanh(z_final). Wait.
        // Spec says: p = 1 / (1 + exp(-z)). This is sigmoid(z).
        // My previous calculation for h used tanh.
        // Let's re-read carefully:
        // h_j = tanh(...)
        // z = sum W2*h + b2
        // p = 1/(1+exp(-z)) -> sigmoid(z)
        // loss = -(y*log(p) + (1-y)*log(1-p)) -> Binary Cross Entropy

        // Recalculate p correctly
        if (z_final > 20.0) p = 1.0;
        else if (z_final < -20.0) p = 0.0;
        else p = 1.0 / (1.0 + exp(-z_final));

        // Loss
        double loss_s = 0.0;
        if (p > 1e-10 && p < 1.0 - 1e-10) {
            loss_s = -(y_s * log(p) + (1.0 - y_s) * log(1.0 - p));
        } else if (p == 0.0) {
            if (y_s == 0.0) loss_s = 0.0;
            else loss_s = 1e-10; // Avoid log(0)
        } else {
            if (y_s == 1.0) loss_s = 0.0;
            else loss_s = 1e-10;
        }
        total_loss += loss_s;

        // Backward pass
        // d_loss/d_p = - (y/p - (1-y)/(1-p))
        double d_loss_dp = -(y_s / p - (1.0 - y_s) / (1.0 - p));

        // d_p/d_z = p * (1 - p)
        double d_p_dz = p * (1.0 - p);

        // d_loss/d_z = d_loss_dp * d_p/dz
        double d_loss_dz = d_loss_dp * d_p_dz;

        // d_loss/d_W2[j] = d_loss/d_z * h[j]
        // d_loss/d_b2 = d_loss/d_z
        for (int j = 0; j < n_hidden; j++) {
            *dW2 + j = d_loss_dz * h[j];
            *db2 = d_loss_dz;
        }

        // d_loss/d_h[j] = d_loss/d_z * W2[j]
        double* dh = new double[n_hidden];
        for (int j = 0; j < n_hidden; j++) {
            dh[j] = d_loss_dz * W2[j];
