    float sum = 0.0f;
    int tile_size = 16;

    for (int k = 0; k < K; k += tile_size) {
        int a_row = row;
        int a_col = k + threadIdx.x;
        int b_row = k + threadIdx.y;
        int b_col = col;

        if (a_row < M && a_col < K && b_row < K && b_col < N) {
            sdata[tid] = A[a_row * K + a_col] * B[b_row * K + b_col];
